["def compute_hash(log_dict: dict):
    return hash(frozenset(log_dict.items()))

def deduplicate(logs):
    seen = set()
    for log in logs:
        log_hash = compute_hash(log)
        if log_hash in seen:
            continue
        seen.add(log_hash)
        yield log

logs = [
    {'id': '1234', 'error': None, 'fruit': 'orange'},
    {'id': '12345', 'error': None, 'fruit': 'apple'},
    {'id': '1234', 'error': None, 'fruit': 'orange'}
]

unique_logs = list(deduplicate(logs))
print(unique_logs)
"]

clean_code:
def compute_hash(log_dict: dict):
    return hash(frozenset(log_dict.items()))

def deduplicate(logs):
    seen = set()
    for log in logs:
        log_hash = compute_hash(log)
        if log_hash in seen:
            continue
        seen.add(log_hash)
        yield log

logs = [
    {'id': '1234', 'error': None, 'fruit': 'orange'},
    {'id': '12345', 'error': None, 'fruit': 'apple'},
    {'id': '1234', 'error': None, 'fruit': 'orange'}
]

unique_logs = list(deduplicate(logs))
print(unique_logs)

