from fastapi.responses import RedirectResponse
from fastapi.templating import Jinja2Templates
from typing import Optional
from starlette import status

app = FastAPI()
templates = Jinja2Templates(directory="templates")

session_store = {}

@app.get('/', response_class=HTMLResponse, name='homepage')
async def get_main_data(request: Request, session_id: Optional[str] = None):
    data = session_store.pop(session_id, {})
    return templates.TemplateResponse('home.html', {'request': request, **data})

@app.post('/', name='homepage_post')
async def post_main_data(request: Request, file: str = Form(...)):
    session_id = str(hash(file))
    session_store[session_id] = {'result': "Processed Data"}
    
    return RedirectResponse(url=f"/?session_id={session_id}", status_code=status.HTTP_303_SEE_OTHER)
"]

